use vstd::prelude::*;

verus! {
    fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
        requires
            list.len() > 0,
            0 < n < list.len(),
        ensures
            new_list.len() == list.len(),
            new_list == list[n..].to_vec() + list[0..n].to_vec(),
    {
        let len = list.len();
        let mut new_list: Vec<i32> = Vec::new();
        
        // Append elements from index n to the end of the list
        for i in n..len {
            new_list.push(list[i]);
        }
        
        // Append elements from index 0 to n-1
        for i in 0..n {
            new_list.push(list[i]);
        }
        
        new_list
    }
}
